(function(){
  'use strict';
  const E=window.MenuWiseEngine,D=window.MenuWiseData,M=window.MenuWiseDecisions,L=window.MenuWiseI18n,C=window.MenuWiseCharts,I=window.MenuWiseImport;
  const KEY='menuwise.v2',LEGACY='menuwise.v1';let storageProblem=false,damaged=false,state;
  try{const raw=localStorage.getItem(KEY)||localStorage.getItem(LEGACY);if(raw)state=M.restore(JSON.parse(raw));}catch{storageProblem=true;damaged=true;}
  if(!state)state={schemaVersion:2,data:E.sample(),lang:'en',mode:'basic',started:false,scenarios:[],configs:{}};
  L.set(state.lang);const T=L.say,t=L.t,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cash=L.money,num=L.num,delta=n=>(n>0?'+':'')+cash(n),percent=n=>Number.isFinite(n)?num(n*100,1)+'%':'—';
  const navs=['welcome','overview','menu','pricing','breakeven','capacity','compare','history'];
  let route=location.hash.slice(1)||(!state.started?'welcome':'overview');if(route==='reports')route='history';if(![...navs,'data','models'].includes(route))route='overview';
  let result=null,dataDraft=null,dirtyData=false,reportId='current',compareIds=new Set(),importState=null,selectedDish=state.data.dishes[0]?.id,simulationValue=null,chartSort='contribution';
  const paths={bowl:'<path d="M3 12h18c-1 11-17 11-18 0ZM7 3c-3 3 3 3 0 6m5-6c-3 3 3 3 0 6m5-6c-3 3 3 3 0 6"/>',welcome:'<path d="m3 10 9-7 9 7v11H3ZM9 21v-8h6v8"/>',overview:'<path d="M5 20V13m7 7V8m7 12V3" stroke-width="2.5"/>',menu:'<path d="M4 3v6c0 4 6 4 6 0V3M7 3v18m12 0V3c-5 3-5 10 0 10"/>',pricing:'<path d="m3 11 8-8h9v9l-9 9-8-8Z"/><circle cx="16" cy="7" r="1"/>',breakeven:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><path d="m12 12 8-8"/>',capacity:'<path d="M6 14c-7-1-4-10 2-8 1-5 7-5 8 0 6-2 9 7 2 8v7H6ZM6 17h12"/>',compare:'<path d="M12 3v18M6 21h12M3 7h18M6 7 2 16h8Zm12 0-4 9h8Z"/>',history:'<path d="M3 7v5h5M3 12a9 9 0 1 1 3 7M12 7v6l4 2"/>',data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',models:'<path d="M12 5c-3-3-7-3-10-2v17c4-1 7-1 10 2 3-3 6-3 10-2V3c-3-1-7-1-10 2Zm0 0v17"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',save:'<path d="M12 2v14m-5-5 5 5 5-5M4 18v4h16v-4"/>',export:'<path d="M12 15V2m-5 5 5-5 5 5M4 13v8h16v-8"/>',plus:'<path d="M12 4v16M4 12h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',hamburger:'<path d="M3 6h18M3 12h18M3 18h18"/>',print:'<path d="M6 8V2h12v6M6 18H2V8h20v10h-4M6 14h12v8H6Zm12-3h.01"/>',settings:'<path d="m9 3-1 3-3 1v4l-2 2 2 3h3l2 4h4l2-4h3l2-3-2-2V7l-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>'};
  const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.info}</svg>`;
  const button=(label,action,style='',ico='',attr='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attr}>${ico?icon(ico):''}<span>${label}</span></button>`;
  const link=(label,to,style='',ico='')=>`<a class="btn ${style}" href="#${to}">${ico?icon(ico):''}<span>${label}</span></a>`;
  const badge=(label,style='')=>`<span class="badge ${style}">${label}</span>`;
  const note=(text,style='')=>`<div class="note ${style}">${icon('info')}<div>${text}</div></div>`;
  const cashSafe=(n,known=true,dp=0)=>known?cash(n,dp):t('unknown');
  const dish=(d,data=state.data)=>L.dish(d,data),restaurant=(data=state.data)=>L.restaurant(data);
  const altName=id=>t(id==='priceA'?'priceAStrategy':id==='priceB'?'priceBStrategy':id);
  const width=()=>innerWidth<680?420:700;
  function persist(){if(damaged){storageProblem=true;return false;}try{localStorage.setItem(KEY,JSON.stringify(state));storageProblem=false;return true;}catch{storageProblem=true;toast(t('storageError'));return false;}}
  function toast(text){const el=$('#toast');el.textContent=storageProblem?t(damaged?'badStorage':'storageError'):text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500);}
  function navigate(view){if(location.hash==='#'+view){route=view;render();}else location.hash=view;}
  function pageHead(heading,description,actions=''){return`<div class="page-head"><div><h1>${heading}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
  function modeSwitch(){return`<div class="segmented mode-control" aria-label="${T('Input detail','输入详细程度')}">${['basic','advanced'].map(v=>button(t(v),'mode',state.mode===v?'selected':'','',`data-mode="${v}" aria-pressed="${state.mode===v}"`)).join('')}</div>`;}
  function field(key,value,options={}){const{min=0,max=1e6,step='.01',optional=false,type='number',label=t(key),hint='',name=key}=options;return`<label class="field"><span>${label}${optional?` <small>${t('optional')}</small>`:''}</span><input name="${name}" aria-label="${esc(label)}" type="${type}" value="${esc(value??'')}" ${type==='number'?`min="${min}" max="${max}" step="${step}" inputmode="decimal"`:'maxlength="120"'} ${optional?'':'required'}>${hint?`<small>${hint}</small>`:''}</label>`;}
  function selectDish(id){return`<label class="field"><span>${T('Choose a dish','选择菜品')}</span><select name="dishId" aria-label="${T('Choose a dish','选择菜品')}">${state.data.dishes.map(d=>`<option value="${esc(d.id)}" ${id===d.id?'selected':''}>${esc(dish(d))}</option>`).join('')}</select></label>`;}
  function period(){const d=state.data,s=d.settings;return`<div class="period"><span><strong>${esc(restaurant())}</strong> <span class="muted">· ${d.source==='sample'?t('sample'):T('Your restaurant','你的餐厅')}</span></span><span>${T('Monthly','按月分析')} · ${s.daysKnown===false?T('Trading days not set','营业日尚未填写'):T(`${s.days} trading days`,`${s.days} 个营业日`)}</span></div>`;}
  function metrics(data=state.data){const b=E.totals(data),k=E.completeness(data);return`<div class="metrics">${[['revenue',b.revenue,true,T('Recorded price × portions','录入售价 × 销量')],['contribution',b.contribution,true,T('Revenue − variable costs','收入 − 变动成本')],['fixed',b.fixed,k.fixed,T('Shared + avoidable costs','共享 + 可避免固定成本')],['profit',b.profit,k.fixed,T('Contribution − fixed costs','贡献 − 固定成本')]].map(([label,value,known,help],i)=>`<div class="metric" style="--metric-accent:${['#7765e8','#3389ed','#4aadd4','#ff702d'][i]}"><span>${t(label)}</span><strong class="num ${value<0&&known?'negative':''}">${cashSafe(value,known)}</strong><small>${known?help:T('Enter fixed costs to calculate','填写固定成本后计算')}</small></div>`).join('')}</div>`;}
  function missingNote(data=state.data){const k=E.completeness(data),items=[];if(!k.fixed)items.push(T('fixed costs','固定成本'));if(!k.days)items.push(T('trading days','营业日'));if(!k.time)items.push(T('bottleneck time','瓶颈用时与产能'));if(!k.demand)items.push(T('demand caps','需求上限'));return items.length?note(`${T('Still to confirm','仍需确认')}：${items.join(T(', ','、'))}. ${T('Contribution and incremental differences remain usable. Absolute profit or operational feasibility is withheld where inputs are missing.','贡献与增量差额仍可分析；缺少相应输入时，不展示绝对利润或宣称运营可行。')} ${link(T('Complete shared data','补充共享数据'),'data','text')}`,'warning'):'';}
  function footer(){return`<footer class="footnote">${icon('info')}<span>${state.data.source==='sample'?T('Sample inputs. ','示例数据。'):''}${T('Conditional estimates, not demand forecasts.','条件估算，不是需求预测。')} <a href="#models">${T('Methods & limitations','方法与限制')}</a></span></footer>`;}
  function profitChart(data=state.data,extraRevenue){const b=E.totals(data),k=E.completeness(data);if(!k.fixed||b.cmRatio===null)return note(T('Enter sales and fixed costs to draw a meaningful profit threshold.','填写销售与固定成本后，可绘制有意义的利润门槛。'));
    const cv=E.cvp(data),threshold=Number.isFinite(cv.breakEven)?cv.breakEven:null,max=Math.max(b.revenue*1.25,threshold?threshold*1.3:0,extraRevenue||0,100),xs=[...new Set([...Array.from({length:31},(_,i)=>max*i/30),b.revenue,...threshold!==null?[threshold]:[]])].sort((a,b)=>a-b);
    const points=xs.map(revenue=>({x:revenue,y:revenue*b.cmRatio-b.fixed,detail:`${t('revenue')}: ${cash(revenue)}<br>${t('profit')}: ${cash(revenue*b.cmRatio-b.fixed)}`}));
    return C.render({series:[{name:T('Operating profit at the current mix','当前组合的经营利润'),points,color:'#7765e8'}],markers:[...(threshold!==null?[{x:threshold,y:0,label:T('Break-even','保本点'),short:T('Break-even','保本点')}]:[]),{x:b.revenue,y:b.profit,color:'#3389ed',label:T('Recorded sales','历史销量'),short:T('Current','当前')}],xLabel:T('Monthly revenue (CNY)','月营业收入（元）'),yLabel:T('Operating profit (CNY)','经营利润（元）'),formatX:v=>num(v/1000,0)+T('k','千'),formatY:v=>num(v/1000,0)+T('k','千'),description:T('Profit at different revenue levels, holding prices, cost behavior and the current sales mix constant. Hover or focus a point for values.','在售价、成本行为和销售组合不变时，不同收入对应的经营利润。悬停或聚焦数据点查看数值。'),width:width(),height:285});
  }
  function scatter(data=state.data,axis='cm'){const b=E.totals(data),points=b.rows.filter(d=>axis!=='perMinute'||d.perMinute!==null).map((d,i)=>({id:d.id,name:dish(d,data),x:d.qty,y:axis==='perMinute'?d.perMinute:d.cm,radius:6+10*Math.sqrt(Math.abs(d.contribution)/Math.max(1,...b.rows.map(x=>Math.abs(x.contribution)))),color:d.cm<0?'#cc4b63':C.palette[i%C.palette.length],accessible:`${dish(d,data)}: ${num(d.qty)}; ${cash(d.cm,2)}`,detail:`${t('qty')}: ${num(d.qty)}<br>${t(axis==='perMinute'?'perMinute':'unitCM')}: ${cash(axis==='perMinute'?d.perMinute:d.cm,2)}<br>${t('totalCM')}: ${cash(d.contribution)}<br><small>${T('Click to compare actions','点击比较经营行动')}</small>`}));return C.render({kind:'scatter',points,xLabel:t('qty'),yLabel:t(axis==='perMinute'?'perMinute':'unitCM')+' (¥)',formatX:v=>num(v),formatY:v=>num(v,1),description:T('Each bubble represents a dish. Bubble area reflects absolute total contribution. Select a bubble to analyze that dish.','每个气泡代表一道菜，面积反映总贡献的绝对值，点击可分析这道菜。'),width:width(),height:285});}
  function dishRows(data=state.data){let rows=E.totals(data).rows;rows=[...rows].sort((a,b)=>chartSort==='qty'?b.qty-a.qty:chartSort==='cm'?b.cm-a.cm:b.contribution-a.contribution);return`<div class="table-scroll"><table class="menu-table"><thead><tr><th>${t('name')}</th><th class="num">${t('qty')}</th><th class="num">${t('unitCM')}</th><th class="num">${t('totalCM')}</th><th class="num">${t('perMinute')}</th><th>${T('Next step','下一步')}</th></tr></thead><tbody>${rows.map(d=>`<tr data-dish-name="${esc(dish(d,data).toLowerCase())}"><td><strong>${esc(dish(d,data))}</strong></td><td class="num">${num(d.qty)}</td><td class="num ${d.cm<=0?'negative':''}">${cash(d.cm,2)}</td><td class="num">${cash(d.contribution)}</td><td class="num">${d.perMinute===null?t('na'):cash(d.perMinute,2)}</td><td>${button(d.cm<=0?T('Review price & cost','检查售价与成本'):T('Compare actions','比较行动'),'analyze-dish','small text','arrow',`data-id="${esc(d.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
  function overview(){const b=E.totals(state.data),k=E.completeness(state.data),opt=k.operations?E.optimize(state.data):null,opportunity=opt?.status==='optimal'?opt.monthlyProfit-b.profit:0;
    return pageHead(T('Your next move, backed by numbers.','让下一步经营，有据可依。'),T('Turn restaurant data into decisions you can act on.','把经营数据，变成可以落实的行动。'),link(T('Manage data','管理数据'),'data')+button(T('Export report','导出报告'),'export-current','primary','export'))+period()+metrics()+missingNote()+`<div class="insight-strip"><span class="insight-icon">${icon(opportunity>0?'overview':'info')}</span><div><h2>${opportunity>0?T('A different kitchen mix could earn more.','调整厨房出品组合，可能获得更多贡献。'):T('Choose one decision to test next.','选择一个经营问题，开始比较。')}</h2><p>${opportunity>0?T('Compare a feasible mix under your entered demand limits.','在已填写的需求限制下，比较可行的出品组合。'):T('Start with a dish, a price, or your monthly profit target.','从一道菜、一个价格，或月度利润目标开始。')}</p></div>${opportunity>0?`<strong class="insight-value">${delta(opportunity)}<small>${T('/ month','/ 月')}</small></strong>`:''}${link(opportunity>0?T('Explore plan','查看方案'):T('Explore menu decisions','查看菜单决策'),opportunity>0?'capacity':'menu','primary','arrow')}</div><div class="charts-grid"><section class="panel"><div class="panel-head"><h2>${T('Where sales turn into profit','销售到哪里，开始产生利润？')}</h2>${badge(t('calculated'))}</div>${profitChart()}</section><section class="panel"><div class="panel-head"><h2>${T('Which dishes deserve attention?','哪些菜值得重点关注？')}</h2></div><p class="caption">${T('Bubble area = absolute total contribution','气泡面积 = 总贡献的绝对值')}</p>${scatter()}</section></div><section class="panel"><div class="panel-head"><h2>${T('Menu performance','菜单经营表现')}</h2>${link(T('Full analysis','完整分析'),'menu','text','arrow')}</div>${dishRows()}</section>${footer()}`;
  }
  function welcome(){const b=E.totals(state.data);return`<div class="welcome"><div class="welcome-grid"><div><h1>${T('A clearer path to<br>your next good decision.','看清经营，<br>再决定下一步。')}</h1><p>${T('Know what a dish earns, what a price change needs, and what your kitchen can actually deliver. MenuWise turns your inputs into choices worth testing.','看清一道菜赚多少、调价需要卖多少，以及厨房到底做得到多少。MenuWise 用你的数据，比较值得试行的经营选择。')}</p><div class="actions">${button(state.started?T('Open my overview','打开经营概览'):T('Explore the sample','体验示例餐厅'),'start','primary','arrow')}${link(T('Enter my data','录入我的数据'),'data')}</div><p class="caption">${T('Works offline. Local files stay on your device.','支持离线使用，文件始终在本机处理。')}</p></div><section class="welcome-preview"><div class="preview-top">${icon('overview')}<span>${esc(restaurant())}</span>${badge(t(state.data.source==='sample'?'sample':'local'))}</div><span class="caption">${t('contribution')}</span><strong class="preview-number">${cash(b.contribution)}</strong><p>${T('What sales leave to cover fixed costs and profit.','收入扣除变动成本后，用于覆盖固定成本与利润的部分。')}</p><div class="mini-bars">${E.totals(state.data).rows.map((d,i)=>`<span style="height:${Math.max(8,d.contribution/Math.max(1,b.contribution)*170)}px;background:${C.palette[i]}"></span>`).join('')}</div><div class="preview-bottom">${T('Calculated from your menu. Never an invented forecast.','根据菜单输入计算，不虚构需求预测。')}</div></section></div><div class="welcome-steps">${[[T('Ask a business question','提出经营问题'),T('Keep a dish? Change a price? Expand the kitchen?','保留一道菜？调整售价？增加产能？')],[T('Compare real alternatives','比较可执行选择'),T('Make costs, sales assumptions and constraints explicit.','把成本、销量假设和约束条件放在明处。')],[T('Test, then review','试行，然后复盘'),T('Save a decision, track actions and record actual results.','保存决策，跟踪行动，记录实际结果。')]].map((a,i)=>`<div><span class="step-index">0${i+1}</span><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join('')}</div>${note(T('Start with four fields per dish: name, price, variable cost and monthly sales. Add operational details when a decision needs them.','每道菜先填四项：名称、售价、变动成本和月销量。需要判断运营可行性时，再补充相关条件。'))}</div>`;}
  function config(type){const prev=state.configs[type],id=prev?.dishId||selectedDish;return{...M.defaults(type,state.data,id),...prev};}
  function menu(){const p=config('menu');return pageHead(T('Which dishes deserve your next investment?','哪些菜，值得下一步投入？'),T('Compare keeping, improving, promoting and removing a dish using relevant costs.','用真正会变化的收入和成本，比较保留、降本、推广与下架。'),modeSwitch())+`<div class="charts-grid"><section class="panel"><div class="panel-head"><h2>${T('Menu opportunity map','菜单经营分布')}</h2><select id="scatterAxis" aria-label="${T('Scatter chart vertical axis','散点图纵轴')}"><option value="cm">${t('unitCM')}</option><option value="perMinute">${t('perMinute')}</option></select></div><div id="menuScatter">${scatter()}</div><p class="caption">${T('Select a dish to compare actions. No industry benchmark is assumed.','点击菜品比较行动，不使用虚构的行业基准。')}</p></section><section class="panel"><div class="panel-head"><h2>${T('Find a dish','找到要分析的菜')}</h2></div><input id="menuSearch" class="search" type="search" placeholder="${T('Search the menu…','搜索菜品…')}" aria-label="${T('Search menu','搜索菜单')}"><div class="dish-pick-list">${state.data.dishes.map(d=>`<button type="button" data-action="analyze-dish" data-id="${esc(d.id)}" data-dish-name="${esc(dish(d).toLowerCase())}"><span>${esc(dish(d))}</span><strong>${cash(E.unit(d).cm,2)} <small>${T('/ portion','/ 份')}</small></strong>${icon('arrow')}</button>`).join('')}</div></section></div><div id="recommendation"></div><form id="decisionForm" data-type="menu" class="panel" novalidate><div class="panel-head"><h2>${T('Compare four actions','比较四种行动')}</h2>${badge(t('assumption'),'blue')}</div><div class="fields four">${selectDish(p.dishId)}${field('saving',p.saving,{optional:true})}${field('improveCost',p.improveCost,{optional:true})}${field('extraQty',p.extraQty,{step:1,optional:true})}${field('promoteCost',p.promoteCost,{optional:true})}</div><details ${state.mode==='advanced'?'open':''}><summary>${T('Removal, cross-sales and replacement assumptions','下架、关联销售与替代业务假设')}</summary><div class="fields four">${field('relatedLoss',p.relatedLoss,{optional:true})}${field('replacement',p.replacement,{optional:true})}${field('replacementMinutes',p.replacementMinutes,{step:.5,max:1e7,optional:true})}${field('exitCost',p.exitCost,{optional:true})}</div><p class="caption">${T('Only avoidable fixed costs disappear. Replacement work may use freed or already-idle capacity, if measured.','只有真正可避免的固定成本才会消失；替代业务可使用释放或已闲置的产能，但需填写用时。')}</p></details><div class="form-footer"><p>${T('All scenarios cover one month. Omitted incremental expenses are treated as zero.','所有方案均按一个月分析；未填的增量费用按零处理。')}</p><button class="btn primary" type="submit">${icon('compare')}${T('Compare actions','比较行动')}</button></div><div class="form-error" role="alert"></div></form><div id="results"></div>${footer()}`;}
  function pricing(){const p=config('pricing'),d=state.data.dishes.find(d=>d.id===p.dishId)||state.data.dishes[0];return pageHead(T('Will a new price actually pay off?','换一个价格，真的更赚钱吗？'),T('Compare profit, demand assumptions, and the volume you need.','比较利润变化、销量假设，以及维持原利润的销量门槛。'),button(T('Save decision','保存决策'),'save-decision','primary','save'))+`<div id="recommendation"></div><div class="pricing-layout"><form id="decisionForm" data-type="pricing" class="panel" novalidate><div class="panel-head"><h2>${T('Your assumptions','你的假设')}</h2></div>${modeSwitch()}<div class="space">${selectDish(p.dishId)}</div><div class="recorded-pair"><span>${T('Recorded price','历史售价')}<strong>${cash(d.price,2)}</strong></span><span>${t('qty')}<strong>${num(d.qty)}</strong></span></div>${['A','B'].map(letter=>`<div class="scenario-input"><h3><i class="series-dot" style="background:${letter==='A'?'#7765e8':'#ff702d'}"></i>${T('Scenario','方案')} ${letter}</h3><div class="fields three">${field('price'+letter,p['price'+letter],{label:T('Price (¥)','售价（元）')})}${field('qty'+letter,p['qty'+letter],{label:T('Portions / month','份数 / 月'),step:1})}${field('extra'+letter,p['extra'+letter],{label:T('Extra expense','新增费用'),optional:true})}</div></div>`).join('')}<details ${state.mode==='advanced'?'open':''}><summary>${T('Sensitivity and commission','敏感性与抽成')}</summary>${field('sensitivity',p.sensitivity,{max:100,optional:true})}<p class="caption">${T('Commission is recalculated at the new price using the rate in shared data. Other unit costs stay fixed.','抽成按共享数据中的费率与新售价重新计算，其他单份成本不变。')}</p></details><button type="submit" class="btn primary full">${T('Compare scenarios','比较方案')}</button><div class="form-error" role="alert"></div></form><section class="panel"><div class="panel-head"><div><h2>${T('Explore the sales threshold','探索销量门槛')}</h2><p>${T('Changing volume is a scenario, not a demand forecast.','调整销量是在测试情景，并非需求预测。')}</p></div></div><div id="pricingChart"></div><div class="simulation"><label for="pricingSlider">${T('Test monthly volume · Scenario A','模拟月销量 · 方案 A')}<output id="pricingVolume">${num(p.qtyA)}</output></label><input type="range" id="pricingSlider" min="0" max="${Math.min(1e6,Math.max(100,d.qty*2,p.qtyA*1.5,p.qtyB*1.5))}" step="1" value="${p.qtyA}" aria-label="${T('Simulated monthly portions','模拟月销量')}"><div id="simulationReadout" class="simulation-readout"></div></div></section></div><div id="results"></div>${footer()}`;}
  function breakeven(){const p=config('breakeven');return pageHead(T('How much do you need to sell?','每天卖多少，才够支撑目标？'),T('Translate a profit goal into sales, then check whether your restaurant can deliver.','把利润目标换成营业收入，再检查需求与厨房是否支撑得住。'),button(T('Save decision','保存决策'),'save-decision','primary','save'))+missingNote()+`<form id="decisionForm" data-type="breakeven" class="panel" novalidate><div class="fields three">${field('target',p.target)}${field('reduction',p.reduction,{optional:true,max:state.data.settings.commonFixed})}${field('increase',p.increase,{optional:true,max:100})}</div><div class="form-footer"><p>${T('Prices and current sales mix stay fixed. Cost reductions need to be achievable.','售价与销售组合保持不变；成本节省需要真实可兑现。')}</p><button class="btn primary" type="submit">${T('Check the target','检查经营目标')}</button></div><div class="form-error" role="alert"></div></form><div id="recommendation"></div><div id="results"></div>${footer()}`;}
  function capacity(){const p=config('capacity');return pageHead(T('Make every bottleneck minute count.','把瓶颈时间，用在更值得的地方。'),T('Find exact whole-portion plans under measured time, demand caps and commitments.','在实测时间、需求上限和最低承诺内，寻找精确的整数出品组合。'),button(T('Save decision','保存决策'),'save-decision','primary','save'))+`<div id="recommendation"></div><form id="decisionForm" data-type="capacity" class="panel" novalidate><div class="panel-head"><h2>${T('Define one shared bottleneck','确定一个共同瓶颈')}</h2>${badge(T('Exact integer optimization','精确整数优化'),'purple')}</div><div class="fields four">${field('capacityMinutes',p.capacityKnown===false?'':p.capacity,{name:'capacity',step:.5,max:10000,optional:true,hint:T('Unknown is different from zero.','尚未填写与零产能是不同的情况。')})}${field('days',p.daysKnown===false?'':p.days??state.data.settings.days,{step:1,min:1,max:31,optional:true})}${field('extraMinutes',p.extraMinutes,{step:.5,max:10000,optional:true})}${field('extraCost',p.extraCost,{optional:true})}</div><div class="table-scroll"><table class="capacity-inputs"><thead><tr><th>${t('name')}</th><th class="num">${t('unitCM')}</th><th>${t('minutes')}</th><th>${t('demand')}</th><th>${t('min')}</th></tr></thead><tbody>${state.data.dishes.map(d=>{const b=p.bounds[d.id]||d;return`<tr data-bound-id="${esc(d.id)}"><td><strong>${esc(dish(d))}</strong></td><td class="num">${cash(E.unit(d).cm,2)}</td>${[['minutes',b.timeKnown===false?'':b.minutes,.5],['demand',b.demandKnown===false?'':b.demand,1],['min',b.min,1]].map(([key,v,step])=>`<td><input aria-label="${esc(dish(d)+' · '+t(key))}" data-bound="${key}" type="number" min="0" max="10000" step="${step}" value="${esc(v??'')}" placeholder="${t('unknown')}"></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>${note(T('Zero minutes means this dish does not use the chosen bottleneck. Blank time or demand is unknown and blocks optimization. Planned output is assumed to sell; other stations, inventory and linked demand are not modeled.','零分钟表示该菜不使用所选瓶颈。用时或需求留空表示未知，系统会暂停优化。计划产量假设全部售出；模型不包含其他工位、库存与联动需求。'))}<div class="form-footer"><p>${T('These are scenario assumptions until you apply them to shared planning data.','这些是当前情景假设；点击应用后才会更新共享计划数据。')}</p><div class="actions">${button(T('Apply to shared data','应用到共享数据'),'apply-capacity') }<button type="submit" class="btn primary">${T('Optimize the plan','优化出品计划')}</button></div></div><div class="form-error" role="alert"></div></form><div id="results"></div>${footer()}`;}
  function constraints(a,data){return badge(t(!a.feasible?'infeasible':a.verified?'verified':'unverified'),!a.feasible?'bad':a.verified?'blue':'warning')+(a.violations?.length?`<p class="cell-note">${a.violations.map(v=>esc(L.issue(v,data))).join('<br>')}</p>`:'');}
  function recommendation(r){let heading,body,value='';const b=r.best,p=r.config,d=r.data.dishes.find(d=>d.id===p.dishId);
    if(r.type==='breakeven'){
      const c=r.cvp[0];
      if(c.status==='incomplete'){heading=T('Add fixed costs before setting a sales target.','补齐固定成本，再确定营业目标。');body=T('Contribution is known; operating profit and break-even are not yet determined.','贡献可以计算，但经营利润与保本线尚无法确定。');}
      else if(c.status==='flat'){heading=T('There is no unique break-even sales level.','当前没有唯一的保本收入。');body=T('Contribution and fixed costs are both zero. Every otherwise feasible sales volume earns zero operating profit; more sales do not improve it.','贡献率和固定成本均为零；满足其他约束的销售量均产生零经营利润，增加销量不能改善利润。');}
      else if(c.status==='boundary'){heading=T('Only zero output can avoid a loss at this mix.','在当前组合下，只有零产出才能避免亏损。');body=T('Negative contribution means each increase in sales reduces profit. Check price and variable costs before pursuing volume.','贡献率为负，增加销售会降低利润。请先检查售价与变动成本。');}
      else if(c.status!=='ok'){heading=T('Fix the contribution economics first.','先修正单份贡献，再谈销量目标。');body=L.issue(c.reason,r.data);}
      else{heading=!c.feasible?T('The current mix needs a different plan.','当前销售组合需要调整。'):!c.verified?T('Validate demand and capacity before committing.','先核实需求和产能，再落实目标。'):T('Test the target with a daily sales plan.','把目标拆成每日计划并试行。');body=T(`The target requires ${cash(c.targetRevenue)} monthly revenue at the current contribution ratio.`, `按当前贡献率，目标需要月收入 ${cash(c.targetRevenue)}。`);if(c.minimumSupplyAdjusted)body+=' '+T(`Minimum commitments raise the executable plan to ${cash(c.plannedRevenue)}.`,`最低供应承诺使实际计划收入提高至 ${cash(c.plannedRevenue)}。`);value=c.dailyTarget===null?'':cash(c.dailyTarget);}
    }else if(!b){heading=r.known.operations?t('noPlan'):T('Complete the operational inputs to build a plan.','补齐运营输入，才能形成出品计划。');body=T('No recommendation is labeled executable until the entered constraints can be satisfied.','只有能够满足已输入约束的方案，才会进入可执行建议。');}
    else if(r.type==='pricing'){
      const label=b.id==='keep'?T('Keep the current price for now.','暂时保持现价。'):T(`Test ${cash(b.price,2)} only after validating demand.`,`先核实需求，再测试 ${cash(b.price,2)} 的价格。`);
      heading=label;body=b.id==='keep'?T('The entered alternatives do not improve feasible monthly profit versus keeping the current price.','在已输入的可行方案中，其他价格没有比现价带来更高的月度利润。'):b.requiredQty===null?T('This price has nonpositive contribution and cannot preserve the baseline profit by increasing volume.','此价格下单份贡献非正，无法通过增加销量维持原利润。'):T(`At least ${num(b.requiredQty)} portions/month preserve current profit, including extra expenses.`,`包含新增费用后，每月至少销售 ${num(b.requiredQty)} 份才能维持原利润。`);value=delta(b.delta);
    }else if(r.type==='menu'){
      heading=altName(b.id);body=b.id==='keep'?T(`This dish currently contributes ${cash(E.unit(d).cm*d.qty)} per month. None of the entered feasible changes improves on keeping it.`,`这道菜当前月贡献为 ${cash(E.unit(d).cm*d.qty)}；输入的其他可行行动没有比保留现状更好。`):T(`This option has the highest incremental profit among the entered feasible alternatives. Its advantage is ${delta(b.delta)} per month, before any unmodeled effects.`,`在已输入的可行选项中，此方案的增量利润最高，每月差额为 ${delta(b.delta)}，尚未计入未建模的影响。`);value=delta(b.delta);
    }else{heading=altName(b.id);body=T('The comparison includes all original fixed costs and the entered expansion expense. Each planned portion must actually sell.','比较已计入全部原固定成本与输入的扩容费用；计划中的每一份都需要实际售出。');value=delta(b.delta);}
    return`<div class="insight-strip recommendation"><span class="insight-icon">${icon('info')}</span><div><span class="eyeline">${t('conditional')}</span><h2>${heading}</h2><p>${body}${r.type!=='breakeven'&&b&&!b.verified?' '+T('Financial comparison only: operational feasibility is not fully checked.','目前仅完成财务比较，运营可行性尚未完整检查。'):''}</p></div>${value?`<strong class="insight-value">${value}<small>${r.type==='breakeven'?T('/ day needed','/ 日所需收入'):T('/ month vs baseline','/ 月，相对基准')}</small></strong>`:''}</div>`;
  }
  function alternativesTable(r){return`<div class="table-scroll"><table class="comparison-table"><thead><tr><th>${T('Strategy','行动方案')}</th>${r.type==='pricing'?`<th class="num">${t('price')}</th><th class="num">${t('qty')}</th>`:''}<th class="num">${t('profit')} ${T('/ month','/ 月')}</th><th class="num">${t('delta')}</th><th>${T('Constraint check','约束检查')}</th></tr></thead><tbody>${r.alternatives.map(a=>`<tr class="${r.best?.id===a.id?'selected-row':''}"><td><strong>${altName(a.id)}</strong>${r.best?.id===a.id?badge(T('Best entered option','输入选项中最优'),'purple'):''}</td>${r.type==='pricing'?`<td class="num">${cash(a.price,2)}</td><td class="num">${num(a.qty)}</td>`:''}<td class="num">${r.known.fixed?cash(a.profit):t('unknown')}</td><td class="num ${a.delta<0?'negative':'positive'}"><strong>${delta(a.delta)}</strong></td><td>${constraints(a,r.data)}</td></tr>`).join('')}</tbody></table></div>`;}
  function impactBars(r){const alts=r.alternatives.filter(a=>Number.isFinite(a.delta));const min=Math.min(0,...alts.map(a=>a.delta)),max=Math.max(1,...alts.map(a=>a.delta)),range=max-min,zero=-min/range*100;return`<div class="impact-bars" role="img" aria-label="${esc(T('Profit differences versus baseline','相对基准的利润差额'))}">${alts.map(a=>`<div class="impact-row"><span>${altName(a.id)}</span><div class="impact-track"><i class="zero-rule" style="left:${zero}%"></i><b style="left:${Math.min(zero,(a.delta-min)/range*100)}%;width:${Math.max(.3,Math.abs(a.delta)/range*100)}%;background:${a.delta<0?'#cc4b63':'#7765e8'}"></b></div><strong class="num ${a.delta<0?'negative':'positive'}">${delta(a.delta)}</strong></div>`).join('')}<p class="caption">${T('Zero marks the recorded baseline; bars show signed profit differences.','零点为历史经营基准；条形表示有正负方向的利润差额。')}</p></div>`;}
  function assumptions(r){const p=r.config,d=r.data.dishes.find(d=>d.id===p.dishId),s=r.data.settings,items=[];
    if(r.type==='pricing')items.push(T(`A: ${cash(p.priceA,2)}, ${num(p.qtyA)} portions and ${cash(p.extraA)} extra expense. B: ${cash(p.priceB,2)}, ${num(p.qtyB)} portions and ${cash(p.extraB)} expense.`,`A：售价 ${cash(p.priceA,2)}、销量 ${num(p.qtyA)} 份、新增费用 ${cash(p.extraA)}；B：售价 ${cash(p.priceB,2)}、销量 ${num(p.qtyB)} 份、新增费用 ${cash(p.extraB)}。`),T('Demand is entered by you. Commission changes with price; other unit costs and other dishes stay unchanged.','需求由你输入。抽成随价格变化，其他单份成本与其他菜品保持不变。'),T(`The ±${num(p.sensitivity)}% demand stress is a scenario range, not a probability forecast.`,`±${num(p.sensitivity)}% 的销量压力只是情景范围，并非概率预测。`));
    if(r.type==='menu')items.push(T(`Cost savings of ${cash(p.saving,2)} per portion must preserve quality and recorded volume. Setup expense is ${cash(p.improveCost)}.`,`每份节省 ${cash(p.saving,2)} 的成本，需保持品质与原销量；实施费用为 ${cash(p.improveCost)}。`),T(`Promotion assumes ${num(p.extraQty)} additional portions for ${cash(p.promoteCost)}. Removal avoids only ${cash(d.avoidable)} of dedicated monthly fixed costs.`,`推广假设增加 ${num(p.extraQty)} 份、费用 ${cash(p.promoteCost)}；下架只节省 ${cash(d.avoidable)} 的专属月固定成本。`),T(`Removal also includes ${cash(p.relatedLoss)} lost cross-sales contribution, ${cash(p.replacement)} replacement contribution and ${cash(p.exitCost)} exit expense.`,`下架还计入 ${cash(p.relatedLoss)} 的关联贡献损失、${cash(p.replacement)} 的替代贡献与 ${cash(p.exitCost)} 的退出费用。`));
    if(r.type==='breakeven')items.push(T('Prices, variable cost behavior and the recorded sales mix remain constant within the relevant operating range.','在相关经营范围内，售价、变动成本行为与历史销售组合保持不变。'),T(`The fixed-cost saving of ${cash(p.reduction)} must be achievable. The ${num(p.increase)}% variable-cost increase is a stress scenario.`,`固定成本节省 ${cash(p.reduction)} 需要真实可兑现；变动成本上涨 ${num(p.increase)}% 是压力情景。`),T('Average daily volumes may be fractional. Use the kitchen module for whole-portion plans; higher minimum commitments can raise the executable sales requirement.','每日平均销量可以是小数；整数出品计划请使用厨房模块。较高的最低供应承诺可能抬高实际所需收入。'));
    if(r.type==='capacity')items.push(T(`One shared bottleneck: ${num(p.capacity)} minutes/day. Expansion adds ${num(p.extraMinutes)} minutes for ${cash(p.extraCost)} per day.`,`一个共同瓶颈：每日 ${num(p.capacity)} 分钟。扩容增加 ${num(p.extraMinutes)} 分钟，日费用 ${cash(p.extraCost)}。`),T('Whole portions, measured half-minute resource units, independent demand caps and minimum commitments. All output is assumed to sell.','整数份数、以半分钟计量的实测用时、独立需求上限与最低承诺；假设所有计划产量均能售出。'),T('Original fixed costs stay in the calculation, even for a zero-output dish. This is scheduling, not a formal removal decision.','全部原固定成本保留，即使某道菜产量为零。这是排产分析，并非正式下架决策。'));
    if(!r.known.operations)items.push(T('Some operational inputs are unknown. The financial comparison does not establish that demand or kitchen capacity can support the action.','部分运营输入未知；财务比较不代表需求或厨房产能能够支撑行动。'));
    items.push(T('Peak-hour queues, linked demand, quality, inventory and other bottlenecks may change the outcome. Operating profit excludes income tax, financing and cash-flow timing.','高峰排队、联动需求、品质、库存与其他瓶颈可能改变结果。经营利润不含所得税、融资和现金流时点影响。'));return items;
  }
  function actionSteps(r){const b=r.best,p=r.config;return{
    pricing:[T('Verify actual selling price, commission and promotion expense before starting a small price test.','先核实实收售价、抽成和活动费用，再进行小范围价格测试。'),b?.requiredQty!==null&&b?.requiredQty!==undefined?T(`Track monthly-equivalent sales against ${num(b.requiredQty)} portions, plus total contribution across the rest of the menu.`,`跟踪折算月销量是否达到 ${num(b.requiredQty)} 份，同时观察其余菜单的总贡献。`):T('Track portions, realized contribution and any substitution away from other dishes.','跟踪销量、实际贡献及对其他菜品的替代影响。'),T('Record actual results in Decision history. Continue only if the full restaurant contribution supports the extra expense.','在决策历史中记录实际结果；只有全店贡献能够覆盖新增费用时，才继续执行。')],
    menu:[T('Verify ingredient usage, waste and genuinely cancelable costs with invoices and preparation records.','根据票据和制作记录，核实食材用量、损耗与真正可取消的费用。'),T('Trial the selected change on a limited scale; record portions, cost per portion and effects on associated sales.','小范围试行所选行动；记录销量、单份成本与关联销售变化。'),T('Compare actual incremental contribution with the trial expense and review customer feedback before expanding.','比较实际新增贡献与试行费用，并结合顾客反馈决定是否扩大。')],
    breakeven:[T('Reconcile shared fixed costs, dish-specific fixed costs and variable costs without duplication.','核对共享固定成本、菜品专属固定成本与变动成本，避免重复。'),T('Translate the target into daily sales, then verify demand and measured bottleneck time before committing.','把目标拆成每日销售计划，再核实需求与实测瓶颈时间。'),T('Review actual contribution ratio weekly. Recalculate if prices, mix, costs or commitments change.','每周检查实际贡献率；售价、组合、成本或承诺变化后重新计算。')],
    capacity:[T('Measure the selected bottleneck, excluding idle time and time at unrelated workstations.','实测所选瓶颈的有效工作时间，不混入闲置时间或无关工位工时。'),T('Use the integer plan as a prep and ordering guide only after confirming demand, inventory and service commitments.','核实需求、库存与服务承诺后，再将整数计划用于备料和接单。'),T('Record sales, waste, stockouts and actual bottleneck minutes. Re-optimize before committing to permanent expansion.','记录实售、报废、缺货及实际瓶颈分钟；永久扩容前重新优化。')]
    }[r.type]||[];}
  function followUp(r){return`<div class="two-column space"><section class="panel"><div class="panel-head"><h2>${T('What to do next','接下来怎么做')}</h2>${button(T('Save decision','保存决策'),'save-decision','small','save')}</div><ol class="action-steps">${actionSteps(r).map(s=>`<li>${s}</li>`).join('')}</ol><div class="review-kpis"><strong>${T('Measure','衡量指标')}</strong><span>${T('Realized contribution · Actual portions · Incremental expense · Bottleneck minutes','实际贡献 · 实售份数 · 新增费用 · 瓶颈分钟')}</span></div></section><section class="panel"><div class="panel-head"><h2>${T('Assumptions to verify','需要验证的前提')}</h2>${badge(t('assumption'),'blue')}</div><ul class="assumptions">${assumptions(r).map(s=>`<li>${s}</li>`).join('')}</ul></section></div>`;}
  function priceChart(r){const d=r.data.dishes.find(d=>d.id===r.config.dishId),p=r.config,a=r.alternatives[1],b=r.alternatives[2],max=Math.min(1e6,Math.ceil(Math.max(100,d.qty*2,p.qtyA*1.2,p.qtyB*1.2)));
    const xs=[...new Set([...Array.from({length:31},(_,i)=>Math.round(max*i/30)),p.qtyA,p.qtyB,...[a.requiredQty,b.requiredQty].filter(v=>v!==null&&v<=max)])].sort((a,b)=>a-b);
    const series=[['A',p.priceA,p.extraA,'#7765e8'],['B',p.priceB,p.extraB,'#ff702d']].map(([id,price,extra,color])=>({name:T('Scenario','方案')+' '+id+` · ${cash(price,2)}`,color,points:xs.map(qty=>{const s=E.priceScenario(r.data,d.id,{price,qty,extra});return{x:qty,y:s.delta,detail:`${t('qty')}: ${num(qty)}<br><strong>${delta(s.delta)} ${T('/ month','/ 月')}</strong><br><small>${s.feasible?(s.verified?t('verified'):t('unverified')):t('infeasible')}</small>`};})}));
    const markers=[{x:p.qtyA,y:a.delta,label:T('Scenario A input','方案 A 输入'),short:'A',color:'#7765e8'},...(a.requiredQty!==null&&a.requiredQty<=max?[{x:a.requiredQty,y:E.priceScenario(r.data,d.id,{price:p.priceA,qty:a.requiredQty,extra:p.extraA}).delta,label:T(`First whole-portion threshold: ${num(a.requiredQty)}`,`整数份数门槛：${num(a.requiredQty)}`),short:T(`Threshold ${num(a.requiredQty)}`,`门槛 ${num(a.requiredQty)}`),color:'#ff702d'}]:[])];
    return C.render({series,markers,xLabel:t('qty'),yLabel:T('Profit difference vs baseline (CNY)','相对基准利润差额（元）'),formatX:v=>num(v),formatY:v=>Math.abs(v)>=1000?num(v/1000,1)+T('k','千'):num(v),description:T('Each line recalculates contribution and extra expense for its entered price at different sales volumes.','每条线按对应售价、不同销量和新增费用，重新计算利润差额。'),width:width(),height:320});
  }
  function standardResults(r){let extra='';if(r.type==='pricing')extra=`<div class="two-column space"><section class="panel"><h2>${T('Sales needed to preserve profit','维持原利润需要的销量')}</h2><div class="thresholds">${r.alternatives.slice(1).map(a=>`<div><span>${altName(a.id)}</span><strong>${a.requiredQty===null?T('Not achievable','无法达到'):num(a.requiredQty)}</strong><small>${T('whole portions / month, including extra expense','整数份 / 月，已计新增费用')}</small>${a.maxQtyToMaintain!==null?`<p class="negative">${T(`With negative margin, no more than ${num(a.maxQtyToMaintain)} portions.`,`负贡献下，最多只能销售 ${num(a.maxQtyToMaintain)} 份。`)}</p>`:''}</div>`).join('')}</div></section><section class="panel"><h2>${T('Demand stress test · Scenario A','销量压力测试 · 方案 A')}</h2><div class="table-scroll"><table><thead><tr><th>${T('Volume change','销量变化')}</th><th class="num">${t('qty')}</th><th class="num">${t('delta')}</th><th>${T('Check','检查')}</th></tr></thead><tbody>${r.sensitivity.map(a=>`<tr><td>${a.change>0?'+':''}${num(a.change)}%</td><td class="num">${num(a.qty)}</td><td class="num ${a.delta<0?'negative':'positive'}">${delta(a.delta)}</td><td>${badge(t(a.feasible?'conditional':'infeasible'),a.feasible?'':'bad')}</td></tr>`).join('')}</tbody></table></div></section></div>`;
    if(r.type==='menu'){const d=r.data.dishes.find(d=>d.id===r.config.dishId);extra=`<div class="panel space"><div class="panel-head"><h2>${T('What removal really changes','下架真正会改变什么')}</h2></div><div class="summary-metrics three"><div><span>${T('Lost contribution / month','失去的月贡献')}</span><strong>${cash(r.lostContribution)}</strong></div><div><span>${T('Avoidable fixed costs / month','可避免的月固定成本')}</span><strong>${cash(d.avoidable)}</strong></div><div><span>${T('Freed bottleneck minutes / month','释放的月瓶颈分钟')}</span><strong>${d.timeKnown===false?t('unknown'):num(r.freedMinutes,1)}</strong></div></div><p class="caption">${T('Shared rent and fixed salaries stay. Replacement activity may use spare capacity, but its contribution and demand must be validated separately.','共享房租与固定工资保留。替代业务可以利用闲置产能，但其贡献与需求需要单独验证。')}</p></div>`;}
    if(r.type==='capacity')extra=capacityPlans(r);
    return`<section class="panel space"><div class="panel-head"><h2>${T('Compare the alternatives','比较备选行动')}</h2>${badge(t('conditional'),'purple')}</div>${alternativesTable(r)}${impactBars(r)}</section>${extra}${followUp(r)}`;
  }
  function capacityPlans(r){const plans=[['optimized',r.optimizer],['expanded',r.expanded]].filter(([,o])=>o.status==='optimal');if(!plans.length)return note((r.optimizer.reason?L.issue(r.optimizer.reason,r.data):T('No valid plan.','暂无有效计划。')),'warning');
    const bestId=r.best?.id==='expanded'?'expanded':'optimized';return`<section class="panel space"><div class="panel-head"><h2>${T('Exact daily production plans','每日整数出品计划')}</h2>${badge(T('Exact optimum for this model','本模型的精确最优解'),'purple')}</div><p class="caption">${T('Both plans are shown. Daily integer repetition can differ from the fractional recorded daily average.','同时展示两种计划。每日重复的整数方案可能不同于历史销量的日均小数。')}</p><div class="table-scroll"><table><thead><tr><th>${t('name')}</th><th class="num">${T('Recorded daily average','历史日均')}</th>${plans.map(([id])=>`<th class="num">${altName(id)}</th>`).join('')}<th class="num">${t('demand')}</th><th class="num">${t('min')}</th></tr></thead><tbody>${r.data.dishes.map((d,i)=>`<tr><td>${esc(dish(d,r.data))}</td><td class="num">${r.known.days?num(d.qty/(r.config.days||r.data.settings.days),1):'—'}</td>${plans.map(([id,o])=>`<td class="num ${id===bestId?'positive':''}"><strong>${o.rows[i].qty}</strong></td>`).join('')}<td class="num">${r.config.bounds[d.id].demand}</td><td class="num">${r.config.bounds[d.id].min}</td></tr>`).join('')}<tr class="total-row"><td>${T('Daily contribution','每日贡献')}</td><td></td>${plans.map(([,o])=>`<td class="num">${cash(o.contribution)}</td>`).join('')}<td colspan="2"></td></tr><tr><td>${T('Used / available minutes','已用 / 可用分钟')}</td><td></td>${plans.map(([,o])=>`<td class="num">${num(o.usedMinutes,1)} / ${num(o.capacity,1)}</td>`).join('')}<td colspan="2"></td></tr></tbody></table></div>${r.incrementalCapacity?note(T(`Extra capacity adds at most ${cash(r.incrementalCapacity.dailyContribution)} daily contribution. After the entered daily expense, the incremental monthly gain versus the existing-capacity optimum is ${delta(r.incrementalCapacity.monthlyNet)}.`,`增加产能最多新增每日贡献 ${cash(r.incrementalCapacity.dailyContribution)}。扣除输入的日费用后，相对原产能最优方案的月度增量为 ${delta(r.incrementalCapacity.monthlyNet)}。`)):''}</section>`;
  }
  function cvpResults(r){const c=r.cvp[0],valid=['ok','flat','boundary'].includes(c.status);if(!valid)return note(L.issue(c.reason,r.data),'warning')+followUp(r);
    const metric=(label,value,help)=>`<div><span>${label}</span><strong>${value}</strong><small>${help}</small></div>`;
    return`<section class="panel space"><div class="summary-metrics four">${metric(T('Monthly break-even','月保本收入'),c.status==='flat'?T('No unique threshold','无唯一门槛'):cash(c.breakEven),T('Revenue, not profit','这是收入，不是利润'))}${metric(T('Daily break-even','日保本收入'),cash(c.dailyBreakEven),T('Average across trading days','按营业日平均'))}${metric(T('Target daily revenue','目标日收入'),cash(c.dailyTarget),T(`For ${cash(r.config.target)} monthly profit`,`目标月利润 ${cash(r.config.target)}`))}${metric(T('Margin of safety','收入安全边际'),percent(c.safetyRatio),T('Recorded revenue above break-even','历史收入超过保本线的比例'))}</div></section><div class="charts-grid space"><section class="panel"><div class="panel-head"><h2>${T('Test a revenue level','模拟一个营业收入')}</h2></div>${profitChart(r.data,c.targetRevenue*1.15)}<div class="simulation"><label for="revenueSlider">${T('Monthly revenue scenario','月营业收入情景')}<output id="revenueValue">${cash(r.base.revenue)}</output></label><input type="range" id="revenueSlider" min="0" max="${Math.ceil(Math.max(r.base.revenue,c.targetRevenue,100)*1.5)}" step="1" value="${r.base.revenue}" aria-label="${T('Simulated monthly revenue','模拟月营业收入')}"><div id="revenueReadout" class="simulation-readout">${t('profit')}: <strong>${cash(r.base.profit)}</strong></div></div></section><section class="panel"><h2>${T('Can the target fit the kitchen?','目标能否装进厨房产能？')}</h2><div class="target-check"><strong>${r.known.time&&r.known.days?num(c.targetMinutes/r.data.settings.days,1):t('unknown')}</strong><span>${T('bottleneck minutes needed per day','每日所需瓶颈分钟')}</span></div><p>${T('Available time','可用时间')}: <strong>${r.known.time?num(r.data.settings.capacity,1):t('unknown')}</strong></p>${constraints(c,r.data)}${c.minimumSupplyAdjusted?note(T(`Minimum commitments raise planned monthly revenue to ${cash(c.plannedRevenue)}.`,`最低承诺将计划月收入提高到 ${cash(c.plannedRevenue)}。`)):''}${r.optimizer.status==='optimal'?note(T(`With a different mix, the exact model reaches ${cash(r.optimizer.monthlyProfit)} monthly operating profit under current demand and time inputs.`,`在当前需求与用时输入下，调整组合后的整数模型可达到月经营利润 ${cash(r.optimizer.monthlyProfit)}。`)):''}${link(T('Explore kitchen plans','查看厨房方案'),'capacity','primary','arrow')}</section></div><section class="panel"><div class="panel-head"><h2>${T('Three conditions, one profit goal','三种条件，同一个利润目标')}</h2></div>${cvpTable(r)}<details><summary>${T('Dish-level quantities and minimum commitments','逐菜品销量与最低供应承诺')}</summary><div class="table-scroll"><table><thead><tr><th>${t('name')}</th><th class="num">${T('Planned daily average','计划日均销量')}</th><th class="num">${t('demand')}</th></tr></thead><tbody>${c.rows.map((row,i)=>`<tr><td>${esc(dish(r.data.dishes[i],r.data))}</td><td class="num">${r.known.days?num(row.daily,2):t('unknown')}</td><td class="num">${r.data.dishes[i].demandKnown===false?t('unknown'):num(row.demand)}</td></tr>`).join('')}</tbody></table></div></details></section>${followUp(r)}`;
  }
  function cvpTable(r){return`<div class="table-scroll"><table><thead><tr><th>${T('Operating condition','经营条件')}</th><th class="num">${T('Monthly break-even revenue','月保本收入')}</th><th class="num">${T('Target revenue / day','目标日收入')}</th><th class="num">${T('Planned revenue / day','含最低承诺的计划日收入')}</th><th>${T('Feasibility','可行性')}</th></tr></thead><tbody>${r.cvp.map(c=>`<tr><td><strong>${altName(c.id)}</strong></td><td class="num">${c.status==='flat'?T('No unique threshold','无唯一门槛'):cash(c.breakEven)}</td><td class="num">${cash(c.dailyTarget)}</td><td class="num">${cash(c.plannedDaily)}</td><td>${constraints(c,r.data)}${c.reason?`<p class="cell-note">${esc(L.issue(c.reason,r.data))}</p>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
  function readNumber(input,optional=false,fallback=0){if(input.value.trim()===''){if(optional)return fallback;D.fail('required',{field:input.getAttribute('aria-label')||input.name});}const n=Number(input.value),min=Number(input.min||0),max=Number(input.max===''?1e6:input.max),step=Number(input.step||.01);if(!Number.isFinite(n)||n<min||n>max||Math.abs(n/step-Math.round(n/step))>1e-6)D.fail('numberRange',{field:input.getAttribute('aria-label')||input.name});return n;}
  function collectConfig(form){const type=form.dataset.type,p={};for(const input of form.querySelectorAll('input[name],select[name]'))p[input.name]=input.tagName==='SELECT'?input.value:readNumber(input,!input.required,input.name==='sensitivity'?10:0);
    if(type==='capacity'){p.capacityKnown=form.elements.capacity.value.trim()!=='';p.daysKnown=form.elements.days.value.trim()!=='';p.days=p.daysKnown?p.days:1;p.bounds={};for(const row of form.querySelectorAll('[data-bound-id]')){const minutes=row.querySelector('[data-bound=minutes]'),demand=row.querySelector('[data-bound=demand]'),min=row.querySelector('[data-bound=min]');p.bounds[row.dataset.boundId]={minutes:readNumber(minutes,true),timeKnown:minutes.value.trim()!=='',demand:readNumber(demand,true),demandKnown:demand.value.trim()!=='',min:readNumber(min,true)};}}
    return p;}
  function analyze(showToast=false){const form=$('#decisionForm');if(!form)return;try{const p=collectConfig(form),type=form.dataset.type;rendersResult(M.run(type,state.data,p));state.configs[type]=p;form.querySelector('.form-error').textContent='';persist();if(showToast)toast(T('Calculated using your current assumptions.','已按当前假设完成计算。'));}catch(e){result=null;$('#results').innerHTML='';if($('#recommendation'))$('#recommendation').innerHTML='';if($('#pricingChart'))$('#pricingChart').innerHTML='';form.querySelector('.form-error').textContent=L.error(e,state.data);}}
  function rendersResult(r){result=r;$('#recommendation').innerHTML=recommendation(r);$('#results').innerHTML=r.type==='breakeven'?cvpResults(r):standardResults(r);if(r.type==='pricing'){$('#pricingChart').innerHTML=priceChart(r);$('#pricingVolume').textContent=num(r.config.qtyA);$('#pricingSlider').value=r.config.qtyA;$('#simulationReadout').innerHTML=`<span>${T('Scenario A vs baseline','方案 A 相对基准')}</span><strong class="${r.alternatives[1].delta<0?'negative':'positive'}">${delta(r.alternatives[1].delta)} ${T('/ month','/ 月')}</strong>`;}}

  function dataView(){dataDraft??=E.clone(state.data);const d=dataDraft,s=d.settings,advanced=state.mode==='advanced';
    const input=(key,value,optional=false,step='.01',max=1e6)=>`<input data-cell="${key}" aria-label="${esc(t(key))}" type="number" min="0" max="${max}" step="${step}" value="${value??''}" ${optional?'':'required'}>`;
    return pageHead(T('One menu. Every decision.','一份经营数据，连接所有决策。'),T('Start with four fields per dish. Add details when they matter to a decision.','每道菜从四项开始，需要判断具体决策时再补充细节。'),modeSwitch()+button(T('Import CSV / Excel','导入 CSV / Excel'),'import','primary','plus'))+`<div class="data-toolbar actions">${button(T('Start a new restaurant','新建餐厅'),'new-restaurant')}${button(T('Load sample','载入示例'),'load-sample')}${button(T('CSV template','CSV 模板'),'template-csv')}${button(T('Excel template','Excel 模板'),'template-xlsx')}${button(T('JSON backup','JSON 备份'),'backup')}${button(T('Restore backup','恢复备份'),'restore')}</div><form id="dataForm" novalidate><section class="panel"><div class="panel-head"><h2>${T('Restaurant & monthly overhead','餐厅与月度固定成本')}</h2>${badge(d.source==='sample'?t('sample'):t('local'))}</div><div class="fields four">${field('restaurantName',restaurant(d),{type:'text'})}${field('commonFixed',s.fixedKnown===false?'':s.commonFixed,{optional:true,hint:T('Exclude dish-specific avoidable costs below. Blank = unknown; 0 = confirmed zero.','不含下方菜品专属可避免成本。留空表示未知，0 表示确认无此成本。')})}${field('days',s.daysKnown===false?'':s.days,{min:1,max:31,step:1,optional:true})}${field('capacityMinutes',s.capacityKnown===false?'':s.capacity,{max:10000,step:.5,optional:true})}</div>${note(T('Variable costs change with portions sold. Shared rent and fixed salaries belong in fixed costs. Platform commission is additional to the entered base variable cost.','变动成本随销售份数变化。共享房租与固定工资放入固定成本；平台抽成在输入的基础变动成本之外另外计入。'))}</section><section class="panel space"><div class="panel-head"><h2>${T('Your menu','你的菜单')}</h2><span class="muted">${d.dishes.length} / 40</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>${t('name')}</th><th>${t('price')}</th><th>${t('variableCost')}</th><th>${t('qty')}</th>${advanced?['feeRate','minutes','demand','min','avoidable'].map(k=>`<th>${t(k)}</th>`).join(''):''}<th>${T('Actions','操作')}</th></tr></thead><tbody>${d.dishes.map(row=>`<tr data-data-id="${esc(row.id)}"><td><input data-cell="name" aria-label="${t('name')}" maxlength="60" value="${esc(dish(row,d))}" required></td><td>${input('price',row.price)}</td><td>${input('variableCost',row.costMode==='total'?row.variableCost:D.baseCost(row))}${advanced?button(T('Cost details','成本明细'),'cost-details','text small','',`data-id="${esc(row.id)}"`):''}</td><td>${input('qty',row.qty,false,1)}</td>${advanced?`<td>${input('feeRate',row.feeRate,true,'.01',100)}</td><td>${input('minutes',row.timeKnown===false?'':row.minutes,true,'.5',10000)}</td><td>${input('demand',row.demandKnown===false?'':row.demand,true,1,10000)}</td><td>${input('min',row.min,true,1,10000)}</td><td>${input('avoidable',row.avoidable,true)}</td>`:''}<td>${button(t('delete'),'delete-dish','text small','','data-id="'+esc(row.id)+'"')}</td></tr>`).join('')}</tbody></table></div><div class="form-footer">${button(T('Add dish','添加菜品'),'add-dish','','plus')}<p>${T('Blank optional expenses = zero. Blank time and demand = unknown. Known zero time is allowed.','选填费用留空按零处理，用时与需求留空表示未知，用时可明确填写为零。')}</p></div></section><div class="sticky-save"><span id="draftStatus">${dirtyData?T('Unsaved changes','有未保存修改'):T('Saved data is shared across all modules.','已保存的数据供所有模块共用。')}</span><button type="submit" class="btn primary">${icon('save')}${T('Save shared data','保存共享数据')}</button></div><div class="form-error" id="dataError" role="alert"></div></form>${footer()}`;
  }
  function captureData(){const form=$('#dataForm');if(!form||!dirtyData)return;const d=dataDraft;if(d.source==='sample'){d.dishes.forEach(x=>x.name=dish(x,d));d.settings.name=restaurant(d);d.source='manual';}const s=d.settings,name=form.elements.restaurantName.value.trim();if(name!==restaurant(d)){s.name=name;s.autoName=false;}for(const [key,inputName,flag,fallback] of [['commonFixed','commonFixed','fixedKnown',0],['days','days','daysKnown',1],['capacity','capacityMinutes','capacityKnown',0]]){const el=form.elements[inputName];s[flag]=el.value.trim()!=='';s[key]=s[flag]?readNumber(el):fallback;}
    for(const row of form.querySelectorAll('[data-data-id]')){const item=d.dishes.find(x=>x.id===row.dataset.dataId);for(const el of row.querySelectorAll('[data-cell]')){const key=el.dataset.cell;if(key==='name'){if(el.value!==dish(item,d))item.name=el.value.trim();continue;}const value=readNumber(el,!el.required);if(key==='variableCost'){if(value!==D.baseCost(item)){item.costMode='total';item.variableCost=value;}}else item[key]=value;if(key==='minutes')item.timeKnown=el.value.trim()!=='';if(key==='demand')item.demandKnown=el.value.trim()!=='';}}}
  function commitData(data){const v=E.validate(data);if(v.errors.length)throw new Error(v.errors.join('\n'));state.data=E.clone(data);state.data.revision=(state.data.revision||0)+1;state.configs={};selectedDish=data.dishes[0].id;state.started=true;dataDraft=null;dirtyData=false;persist();return v;}
  function dialog(title,body,actions=''){const el=$('#dialog');el.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button(t('close'),'close-dialog','icon-button','close')}</div><div class="dialog-body">${body}</div><div class="dialog-error form-error" role="alert"></div>${actions?`<div class="dialog-footer actions">${actions}</div>`:''}`;if(!el.open)el.showModal();}
  function confirmAction(title,body,action){dialog(title,`<p>${body}</p>`,button(t('cancel'),'close-dialog')+button(T('Continue','继续'),action,'primary'));}
  function costDialog(id){captureData();const d=dataDraft.dishes.find(x=>x.id===id);dialog(T('How is this dish’s cost recorded?','这道菜的成本如何记录？'),`<form id="costForm" data-id="${esc(id)}"><label class="field"><span>${T('Use one cost source','选择一种成本来源')}</span><select name="costMode"><option value="total" ${d.costMode==='total'?'selected':''}>${T('Total base variable cost','基础变动成本总额')}</option><option value="detailed" ${d.costMode!=='total'?'selected':''}>${T('Sum of detailed components','成本明细合计')}</option></select></label><div class="fields two">${field('variableCost',D.baseCost(d))}${['food','packaging','labor','other'].map(k=>field(k,d[k],{optional:true})).join('')}</div><p>${T('Commission is added separately. Fixed payroll must not be included as piece-rate labor. Only the chosen cost source is used.','抽成另计，固定工资不能放入计件人工。仅使用所选的成本来源。')}</p></form>`,button(t('cancel'),'close-dialog')+button(T('Apply to draft','应用到草稿'),'apply-cost','primary'));}
  function download(name,content,type='application/octet-stream'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function fileInput(accept,callback){const el=document.createElement('input');el.type='file';el.accept=accept;el.addEventListener('change',()=>el.files[0]&&callback(el.files[0]));el.click();}
  async function openImport(file){try{if(file.size>5*1024*1024)throw new Error(T('Use a file smaller than 5 MB.','请使用小于 5 MB 的文件。'));let sheets=[];if(/\.xlsx$/i.test(file.name)){const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());for(const sheet of wb.worksheets){if(sheet.rowCount>10000||sheet.columnCount>100)throw new Error(T('The sheet is too large. Keep only the menu table.','工作表过大，请只保留菜单表格。'));const rows=[];sheet.eachRow({includeEmpty:true},row=>rows.push(Array.from({length:sheet.columnCount},(_,i)=>row.getCell(i+1).value)));sheets.push({name:sheet.name,rows});}}else if(/\.(csv|tsv)$/i.test(file.name)){let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());}catch{text=new TextDecoder('gb18030').decode(await file.arrayBuffer());}sheets=[{name:file.name,rows:D.parse(text)}];}else throw new Error(T('Use CSV, TSV or XLSX. Save legacy XLS files as XLSX first.','支持 CSV、TSV 或 XLSX，请先将旧版 XLS 另存为 XLSX。'));if(!sheets.length)D.fail('emptyImport');importState={filename:file.name,sheets,sheet:0,headerIndex:0,numberStyle:'dot',costMode:''};resetMapping();importDialog();}catch(e){toast(L.error(e,state.data));}}
  function resetMapping(){const s=importState;s.mapping=D.inferMapping(s.sheets[s.sheet].rows[s.headerIndex]||[]).mapping;s.preview=null;}
  function importDialog(){const s=importState,rows=s.sheets[s.sheet].rows,headers=rows[s.headerIndex]||[];dialog(T('Map your file, preview, then import','映射列，检查预览，再导入'),`<p>${esc(s.filename)} · ${T('Processed only on this device.','仅在本机处理。')}</p><div class="fields two"><label class="field"><span>${T('Worksheet','工作表')}</span><select id="importSheet">${s.sheets.map((x,i)=>`<option value="${i}" ${s.sheet===i?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field"><span>${T('Header row','表头所在行')}</span><select id="importHeader">${rows.slice(0,10).map((_,i)=>`<option value="${i}" ${s.headerIndex===i?'selected':''}>${i+1}</option>`).join('')}</select></label><label class="field"><span>${T('Decimal format','小数格式')}</span><select id="importNumber"><option value="dot" ${s.numberStyle==='dot'?'selected':''}>1,234.50</option><option value="comma" ${s.numberStyle==='comma'?'selected':''}>1.234,50</option></select></label><label class="field"><span>${T('Cost source','成本来源')}</span><select id="importCost"><option value="">${T('Detect; ask if ambiguous','自动识别，歧义时提示')}</option><option value="total" ${s.costMode==='total'?'selected':''}>${T('Total variable cost','变动成本总额')}</option><option value="detailed" ${s.costMode==='detailed'?'selected':''}>${T('Detailed components','成本明细合计')}</option></select></label></div><div class="mapping-grid">${D.fields.map(k=>`<label class="field"><span>${t(k)} ${['name','price','qty'].includes(k)?'*':''}</span><select data-mapping="${k}"><option value="-1">${T('Not provided','未提供')}</option>${headers.map((h,i)=>`<option value="${i}" ${s.mapping[k]===i?'selected':''}>${i+1} · ${esc(typeof h==='object'?'':h)}</option>`).join('')}</select></label>`).join('')}</div><div id="importPreview"></div>`,button(t('cancel'),'close-dialog')+button(T('Preview calculation','预览计算'),'preview-import')+button(T('Replace menu with preview','用预览替换菜单'),'confirm-import','primary','','disabled'));}
  function previewImport(){try{const s=importState;s.preview=D.prepare(s.sheets[s.sheet].rows,state.data,{...s});const p=s.preview,b=E.totals(p.data);$('#importPreview').innerHTML=note(T(`${p.data.dishes.length} dishes · revenue ${cash(b.revenue)} · contribution ${cash(b.contribution)}`,`${p.data.dishes.length} 道菜 · 收入 ${cash(b.revenue)} · 贡献 ${cash(b.contribution)}`))+ (p.resetSample?note(T('Sample overhead, trading days and capacity will be cleared. Enter your restaurant’s actual settings after import.','示例固定成本、营业日和产能将清空，导入后请填写你的实际经营设置。'),'warning'):'')+(p.defaults.length?note(T('Omitted fields: ','缺省字段：')+p.defaults.map(k=>t(k)).join(T(', ','、'))+T('. Expenses/minimums default to zero; time/demand remain unknown.','。费用与最低供应默认为零，用时与需求保持未知。')):'')+dishRows(p.data);$('#dialog .dialog-error').textContent='';$('[data-action="confirm-import"]').disabled=false;}catch(e){importState.preview=null;$('#importPreview').innerHTML='';$('#dialog .dialog-error').textContent=L.error(e,state.data);$('[data-action="confirm-import"]').disabled=true;}}
  function decisionTitle(s){return s.title||t(s.type)+(s.config.dishId?' · '+dish(s.data.dishes.find(d=>d.id===s.config.dishId),s.data):'');}
  function date(value){return new Date(value).toLocaleString(L.lang()==='zh'?'zh-CN':'en-US',{dateStyle:'medium',timeStyle:'short'});}
  function history(){return pageHead(T('Decisions become useful when you follow through.','决策，执行之后更有价值。'),T('Keep the original inputs, track actions and compare the actual outcome.','保留原始输入，跟踪行动，比较实际结果。'),button(T('Export backup','导出备份'),'backup','','export'))+(state.scenarios.length?`<div class="history-grid">${[...state.scenarios].reverse().map(s=>`<article class="panel history-card"><div class="panel-head">${badge(t(s.type),'purple')}${badge(t(s.status),s.status==='reviewed'?'blue':'')}</div><h2>${esc(decisionTitle(s))}</h2><p class="muted">${date(s.created)} · ${esc(restaurant(s.data))}</p><div class="history-impact"><span>${s.type==='breakeven'?T('Target monthly profit','目标月利润'):T('Best feasible difference / month','最佳可行方案月差额')}</span><strong>${s.type==='breakeven'?cash(s.config.target):s.result.best?delta(s.result.best.delta):'—'}</strong></div><p>${s.stepsDone.length}/3 ${T('actions complete','项行动完成')}${s.actuals?' · '+T('Actuals recorded','已记录实际结果'):''}</p>${JSON.stringify(s.data)!==JSON.stringify(state.data)?badge(T('Saved baseline differs from working data','保存基准与当前数据不同'),'orange'):''}${s.legacy?note(T('Legacy inputs recalculated with model 2.0.','旧版输入已按 2.0 模型重新计算。')):''}<div class="actions">${button(T('Review & report','复盘与报告'),'review','','arrow',`data-id="${esc(s.id)}"`)}${button(T('Compare','对比'),'select-compare','text','',`data-id="${esc(s.id)}"`)}${button(t('delete'),'delete-decision','text','',`data-id="${esc(s.id)}"`)}</div></article>`).join('')}</div>`:empty(T('No saved decisions yet.','还没有保存决策。'),T('Compare alternatives in a decision module, then save the scenario.','在决策模块比较备选行动，然后保存方案。'),link(t('pricing'),'pricing','primary')));}
  function empty(title,text,action=''){return`<section class="panel empty"><div class="empty-icon">${icon('compare')}</div><h2>${title}</h2><p>${text}</p>${action}</section>`;}
  function compare(){const records=state.scenarios.filter(s=>compareIds.has(s.id));return pageHead(T('Compare choices side by side.','把不同选择放在一起看。'),T('Each scenario retains its own restaurant inputs. Differences are not additive.','每个方案保留自己的经营输入，方案差额不能直接相加。'))+(state.scenarios.length?`<section class="panel"><div class="compare-picker">${state.scenarios.map(s=>`<label><input type="checkbox" data-compare-id="${esc(s.id)}" ${compareIds.has(s.id)?'checked':''}> ${esc(decisionTitle(s))}<small>${date(s.created)}</small></label>`).join('')}</div><p class="caption">${T('Choose 2–4 decisions.','选择 2–4 个决策。')}</p></section>${records.length>=2?comparison(records):empty(T('Choose at least two saved decisions.','请至少选择两个已保存决策。'),'')}`:empty(T('Save decisions to compare them.','先保存决策，再比较。'),' ',link(t('pricing'),'pricing','primary')));}
  function comparison(records){const bases=records.map(s=>JSON.stringify(s.data));return(bases.some(x=>x!==bases[0])?note(T('Different baseline inputs: compare each gain against its own baseline, and review costs and constraints before choosing.','基准数据不同：每个增量只相对其自身基准；选择前请核对成本与约束。'),'warning'):'')+`<section class="panel space"><div class="table-scroll"><table><thead><tr><th>${T('Decision','决策')}</th><th>${T('Recommended action','建议行动')}</th><th class="num">${T('Baseline profit','基准利润')}</th><th class="num">${T('Conditional profit','条件估算利润')}</th><th class="num">${T('Difference / month','月度差额')}</th><th>${T('Key condition','关键条件')}</th></tr></thead><tbody>${records.map(s=>{const r=s.result,b=r.best;return`<tr><td><strong>${esc(decisionTitle(s))}</strong></td><td>${b?altName(b.id):T('Review target conditions','检查目标条件')}</td><td class="num">${cashSafe(r.base.profit,r.known.fixed)}</td><td class="num">${s.type==='breakeven'?T('Goal: ','目标：')+cash(s.config.target):cash(b?.profit)}</td><td class="num">${b?delta(b.delta):'—'}</td><td>${b?constraints(b,s.data):T('Fixed sales mix; not a forecast','固定销售组合，不是预测')}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
  function saveDialog(){if(!result)return toast(T('Complete a valid analysis first.','请先完成有效分析。'));if(state.scenarios.length>=50)return toast(T('Export a backup and remove an old decision; the limit is 50.','最多保留 50 个决策，请导出备份并删除旧记录。'));dialog(T('Save this decision and its inputs','保存决策与当前输入'),field('title','',{type:'text',optional:true,label:T('Decision name','决策名称')})+`<p>${T('The snapshot remains unchanged when shared data is edited. Reports follow your selected language.','之后修改共享数据不会改变这份快照，报告随所选语言切换。')}</p>`,button(t('cancel'),'close-dialog')+button(t('save'),'confirm-save','primary'));}
  function review(id){const s=state.scenarios.find(x=>x.id===id);if(!s)return;reportId=id;const a=s.actuals||{};dialog(T('Action review & decision report','行动复盘与决策报告'),`<h3>${esc(decisionTitle(s))}</h3><p>${date(s.created)}</p><label class="field"><span>${T('Status','状态')}</span><select id="reviewStatus">${['planned','testing','reviewed'].map(v=>`<option value="${v}" ${s.status===v?'selected':''}>${t(v)}</option>`).join('')}</select></label><div class="review-checks">${actionSteps(s.result).map((text,i)=>`<label><input type="checkbox" data-step="${i}" ${s.stepsDone.includes(i)?'checked':''}> ${text}</label>`).join('')}</div><h3>${T('Actual results for a comparable month','可比月份的实际结果')}</h3><p>${T('Enter all three totals. Include trial expenses in the appropriate actual cost. This is a comparison, not proof that the decision caused the result.','请填写全部三项，试行费用计入相应实际成本。比较结果不代表已证明决策的因果效果。')}</p><form id="actualForm"><div class="fields three">${field('revenue',a.revenue,{optional:true,max:1e9})}${field('variable',a.variable,{optional:true,max:1e9,label:T('Total variable costs','变动成本总额')})}${field('fixed',a.fixed,{optional:true,max:1e9})}</div><label class="field"><span>${T('Review note','复盘备注')}</span><textarea name="note" maxlength="2000">${esc(a.note||'')}</textarea></label></form>${a.revenue!==undefined?note(T(`Actual operating profit: ${cash(a.revenue-a.variable-a.fixed)}.`,`实际经营利润：${cash(a.revenue-a.variable-a.fixed)}。`)):''}`,button(T('Open report','查看报告'),'open-report','','export')+button(T('Save review','保存复盘'),'save-review','primary'));}
  function saveReview(){const s=state.scenarios.find(x=>x.id===reportId),form=$('#actualForm'),values=['revenue','variable','fixed'].map(k=>form.elements[k].value.trim());if(values.some(Boolean)&&!values.every(Boolean))throw new Error(T('Enter revenue, variable costs and fixed costs together.','请同时填写收入、变动成本和固定成本。'));s.status=$('#reviewStatus').value;s.stepsDone=$$('[data-step]:checked').map(el=>Number(el.dataset.step));s.actuals=values.every(Boolean)?{revenue:readNumber(form.elements.revenue),variable:readNumber(form.elements.variable),fixed:readNumber(form.elements.fixed),note:form.elements.note.value,recorded:new Date().toISOString()}:null;persist();}
  function refs(){return`<ul class="references"><li><a href="https://www.accaglobal.com/uk/en/student/exam-support-resources/fundamentals-exams-study-resources/f5/technical-articles/CVP-analysis.html" target="_blank" rel="noopener">ACCA · ${T('Cost–volume–profit analysis','成本—销量—利润分析')}</a></li><li><a href="https://openstax.org/books/principles-managerial-accounting/pages/10-4-evaluate-and-determine-whether-to-keep-or-discontinue-a-segment-or-product" target="_blank" rel="noopener">OpenStax 10.4 · ${T('Keep or discontinue a product','保留或停产决策')}</a></li><li><a href="https://openstax.org/books/principles-managerial-accounting/pages/10-6-evaluate-and-determine-how-to-make-decisions-when-resources-are-constrained" target="_blank" rel="noopener">OpenStax 10.6 · ${T('Constrained resources','受限资源决策')}</a></li></ul>`;}
  function models(){return pageHead(T('Transparent methods. Practical limits.','方法透明，边界明确。'),T('Every recommendation comes from entered data and explicit assumptions.','每项建议都来自输入数据和明确假设。'))+`<section class="panel prose"><h2>${T('What the numbers mean','这些数字代表什么')}</h2><p>${T('Revenue = price × portions. Unit contribution = price − base variable cost − platform commission. Operating profit = total contribution − shared fixed costs − dish-specific avoidable fixed costs. Profit is before tax, interest and owner drawings.','营业收入 = 售价 × 份数。单份贡献 = 售价 − 基础变动成本 − 平台抽成。经营利润 = 总贡献 − 共享固定成本 − 菜品专属可避免固定成本。不含税、利息与业主提款。')}</p><h2>${T('Break-even and target profit','保本与目标利润')}</h2><p>${T('At a constant sales mix, contribution ratio = total contribution / revenue. Break-even revenue = fixed costs / contribution ratio. Target revenue = (fixed costs + target profit) / contribution ratio. No revenue means the mix cannot be inferred. Nonpositive contribution does not support a positive profit target. A zero-cost, zero-margin operation has no unique break-even threshold.','销售组合不变时，贡献率 = 总贡献 / 收入。保本收入 = 固定成本 / 贡献率。目标收入 =（固定成本 + 目标利润）/ 贡献率。零收入无法推断组合；非正贡献无法支撑正利润目标。成本与贡献均为零时，不存在唯一保本门槛。')}</p><h2>${T('Pricing and removal','定价与下架')}</h2><p>${T('Price comparisons replace the selected dish’s contribution and subtract additional expenses. Required portions round upward to whole portions. Demand is editable, never predicted. Removal compares avoidable cost savings plus replacement contribution against lost dish contribution, cross-sales losses and exit costs. Allocated shared costs do not disappear.','定价比较替换所选菜品的贡献，并扣除新增费用。所需份数向上取整。需求由用户编辑，不作预测。下架比较可避免成本节省与替代贡献，并扣除原菜品贡献、关联销售损失和退出费用。分摊的共享成本不会自动消失。')}</p><h2>${T('Kitchen optimization','厨房优化')}</h2><p>${T('Exact bounded integer knapsack maximizes daily contribution with one bottleneck, half-minute time units, integer minimums and demand caps. Zero-time dishes can be chosen up to demand. Fixed costs are unchanged. Expansion compares the exact optimum before and after added time, then deducts the entered daily expense. One daily plan repeats across trading days. The model does not represent multiple stations, simultaneous preparation, labor scheduling, queues or interactions between dishes.','使用精确有界整数背包，在单一瓶颈、半分钟时间粒度、整数最低供应与需求上限下最大化日贡献。零用时菜品可供应至需求上限，固定成本保持不变。扩容比较增加用时前后的精确最优解，再扣除输入的每日费用。每日方案在营业日重复。模型不表示多工位、并行制作、排班、排队或菜品间相互影响。')}</p><h2>${T('Data and rounding','数据与舍入')}</h2><p>${T('All amounts are CNY. Commission rounds half up to cents per portion using integer rate basis points; monetary comparisons use cents. This may differ from platform invoice rounding. Basic cost is exclusive of separately entered commission. Missing operational data blocks optimization and marks financial comparisons as unverified. Imported sample settings are cleared. Charts use model values, with no invented trend or industry threshold.','所有金额为人民币。抽成按每份四舍五入到分，费率用整数基点计算，金额比较采用分。这可能与平台账单汇总舍入不同。基础成本不包含单独填写的抽成。运营数据缺失时不运行优化，并将财务比较标记为未验证。导入真实菜单会清除示例经营设置。图表全部来自模型，不使用虚构趋势或行业门槛。')}</p><h2>${T('References','参考资料')}</h2>${refs()}</section>`;}
  function reportContent(s){const r=s.result,data=r.type==='capacity'?r.constraintData:s.data,b=E.totals(data),a=s.actuals;return`<header class="report-head"><div class="brand">${icon('bowl')} MenuWise</div><span>${T('Decision report','经营决策报告')} · ${date(s.created)}</span></header><h1>${esc(decisionTitle(s))}</h1><p>${esc(restaurant(data))} · ${t(s.status)} · ${T('Model','模型')} 2.0 · ${T('Currency: CNY','币种：人民币')}</p>${s.legacy?note(T('Legacy inputs recalculated with model 2.0; original inputs retained.','旧版输入按 2.0 模型重新计算，保留原始输入。')):''}${recommendation(r)}${metrics(data)}<h2>${T('Alternatives and financial impact','备选行动与财务影响')}</h2>${r.type==='breakeven'?cvpTable(r):alternativesTable(r)}${r.type==='capacity'?capacityPlans(r):r.type==='pricing'?priceChart(r):r.type==='breakeven'?profitChart(data):impactBars(r)}<h2>${T('Implementation & follow-up','执行与跟踪')}</h2><ol>${actionSteps(r).map((x,i)=>`<li>${s.stepsDone?.includes(i)?'☑ ':'☐ '}${x}</li>`).join('')}</ol>${a?`<h2>${T('Recorded actual outcome','已记录实际结果')}</h2><p>${t('revenue')}: ${cash(a.revenue)} · ${T('Variable costs','变动成本')}: ${cash(a.variable)} · ${t('fixed')}: ${cash(a.fixed)}</p><p><strong>${t('profit')}: ${cash(a.revenue-a.variable-a.fixed)}</strong>${Number.isFinite(r.best?.profit)?' · '+T('Difference from estimate: ','相对估算差额：')+delta(a.revenue-a.variable-a.fixed-r.best.profit):''}</p><p>${esc(a.note)}</p><p>${T('Outcome comparison does not establish causation.','结果比较不能证明因果关系。')}</p>`:''}<h2>${T('Assumptions, constraints and risks','假设、约束与风险')}</h2>${"<ul>"+assumptions(r).map(x=>"<li>"+x+"</li>").join("")+"</ul>"}<h2>${T('Saved restaurant inputs','保存的经营输入')}</h2><p>${t('days')}: ${data.settings.daysKnown===false?'—':data.settings.days} · ${t('capacityMinutes')}: ${data.settings.capacityKnown===false?'—':data.settings.capacity} · ${t('commonFixed')}: ${cashSafe(data.settings.commonFixed,r.known.fixed)}</p><div class="table-scroll"><table><thead><tr>${['name','price','variableCost','qty','feeRate','minutes','demand','min','avoidable'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${data.dishes.map(d=>`<tr><td>${esc(dish(d,data))}</td><td>${cash(d.price,2)}</td><td>${cash(D.baseCost(d),2)}</td><td>${num(d.qty)}</td><td>${num(d.feeRate,2)}%</td><td>${d.timeKnown===false?'—':num(d.minutes,1)}</td><td>${d.demandKnown===false?'—':num(d.demand)}</td><td>${num(d.min)}</td><td>${cash(d.avoidable)}</td></tr>`).join('')}</tbody></table></div><h3>${T('Scenario assumptions','方案假设')}</h3><dl class="report-config">${Object.entries(s.config).filter(([k,v])=>typeof v==='number'&&!['capacityKnown','daysKnown'].includes(k)).map(([k,v])=>`<div><dt>${k==='capacity'?t('capacityMinutes'):t(k)}</dt><dd>${num(v,2)}</dd></div>`).join('')}</dl>${r.type==='pricing'?`<p>${T('Whole portions needed to preserve baseline contribution after extra expense','扣除新增费用后维持原贡献所需的整数销量')}: A ${num(r.alternatives[1].requiredQty)} · B ${num(r.alternatives[2].requiredQty)}</p>`:''}<h2>${T('Methods and references','方法与参考')}</h2><p>${T('Conditional estimates from CVP, relevant-cost and incremental analysis, and an exact single-bottleneck integer optimization. Fixed sales mix applies only to CVP. Demand assumptions require a real trial. See the included model guide for formulas and limits.','采用 CVP、相关成本、增量分析与单瓶颈整数精确优化进行条件估算。固定销售组合只适用于 CVP。需求假设需真实试行验证。公式与边界见模型说明。')}</p>${refs()}<footer>${T('Generated locally. No restaurant files uploaded.','本机生成，未上传餐厅文件。')} · MenuWise 2.0</footer>`;}
  function openReport(s){$('#dialog').close();reportId=s.id;const paper=$('#reportPaper');paper.innerHTML=`<div class="report-controls actions">${button(T('Back to app','返回应用'),'close-report')}${button(T('Print / Save PDF','打印 / 保存 PDF'),'print','primary','print')}${button(T('Export HTML','导出 HTML'),'report-html')}${button(L.lang()==='en'?'简体中文':'English','report-language')}</div><article id="reportContent">${reportContent(s)}</article>`;document.body.classList.add('reporting');window.scrollTo(0,0);}
  function reportRecord(){return state.scenarios.find(s=>s.id===reportId)||currentReport;}
  let currentReport=null;
  function render(){C.clear();document.documentElement.lang=L.lang()==='zh'?'zh-CN':'en';document.title='MenuWise · '+t(route);document.querySelector('.skip-link').textContent=T('Skip to content','跳转到主要内容');result=null;
    $('#app').innerHTML=`<aside class="sidebar"><a href="#welcome" class="brand">${icon('bowl')}<strong>MenuWise</strong></a><p class="sidebar-caption">${T('RESTAURANT INTELLIGENCE','餐饮经营决策')}</p><nav aria-label="${T('Main navigation','主导航')}">${navs.map(n=>`<a href="#${n}" class="nav-item ${route===n?'active':''}" ${route===n?'aria-current="page"':''}>${icon(n)}<span>${t(n)}</span></a>`).join('')}<div class="nav-divider"></div>${['data','models'].map(n=>`<a href="#${n}" class="nav-item ${route===n?'active':''}">${icon(n)}<span>${t(n)}</span></a>`).join('')}</nav><div class="sidebar-bottom">${icon('data')}<div><strong>${t('local')}</strong><span>${T('Private by design','数据留在本机')}</span></div><span class="local-dot"></span></div></aside><div class="workspace"><header class="topbar">${button(T('Navigation','导航'),'toggle-nav','mobile-menu icon-button','hamburger')}<div class="breadcrumb">${T('Workspace','工作空间')} <span>/</span> <strong>${t(route)}</strong></div><div class="topbar-right"><div class="language-switch" aria-label="${T('Language','语言')}"><button data-action="language" data-lang="en" class="${L.lang()==='en'?'selected':''}" aria-pressed="${L.lang()==='en'}">EN</button><button data-action="language" data-lang="zh" class="${L.lang()==='zh'?'selected':''}" aria-pressed="${L.lang()==='zh'}">中文</button></div><span class="avatar" aria-hidden="true">MW</span></div></header><main id="main" tabindex="-1">${storageProblem?note(t(damaged?'badStorage':'storageError'),'warning'):''}${({welcome,overview,menu,pricing,breakeven,capacity,data:dataView,compare,history,models}[route])()}</main></div>`;
    if($('#decisionForm'))analyze();document.body.classList.remove('nav-open');}
  async function handleAction(a){const id=a.dataset.id;try{switch(a.dataset.action){
    case 'toggle-nav':document.body.classList.toggle('nav-open');break;
    case 'close-dialog':$('#dialog').close();break;
    case 'start':state.started=true;persist();navigate('overview');break;
    case 'language':if($('#dataForm'))captureData();state.lang=a.dataset.lang;L.set(state.lang);persist();render();break;
    case 'mode':if($('#dataForm'))captureData();state.mode=a.dataset.mode;persist();render();break;
    case 'analyze-dish':selectedDish=id;state.configs.menu=M.defaults('menu',state.data,id);persist();navigate('menu');break;
    case 'save-decision':saveDialog();break;
    case 'confirm-save':{const s=M.snapshot(result.type,result.data,result.config,$('#dialog input[name=title]').value.trim());state.scenarios.push(s);persist();$('#dialog').close();toast(T('Decision saved. Track it in Decision history.','决策已保存，可在决策历史中跟踪。'));break;}
    case 'new-restaurant':confirmAction(T('Start with a blank restaurant?','从空白餐厅开始？'),T('This replaces the working menu after you save. Saved decisions are retained. Export a backup if needed.','保存后将替换当前菜单，已保存的决策保留。需要时请先导出备份。'),'confirm-new');break;
    case 'confirm-new':dataDraft=D.blank();dirtyData=true;$('#dialog').close();render();break;
    case 'load-sample':confirmAction(T('Replace working data with the sample?','用示例替换当前数据？'),T('Current menu and unsaved edits will be replaced. Saved decisions stay. Export a backup first if needed.','当前菜单与未保存修改将被替换，已保存决策保留。需要时请先导出备份。'),'confirm-sample');break;
    case 'confirm-sample':damaged=false;commitData(E.sample());$('#dialog').close();render();break;
    case 'add-dish':captureData();if(dataDraft.dishes.length>=40)D.fail('tooManyDishes');{const d=D.blank().dishes[0];d.id='dish-'+Date.now();dataDraft.dishes.push(d);}dirtyData=true;render();break;
    case 'delete-dish':captureData();if(dataDraft.dishes.length<=1)throw new Error(T('Keep at least one dish.','请至少保留一道菜。'));dataDraft.dishes=dataDraft.dishes.filter(d=>d.id!==id);dirtyData=true;render();break;
    case 'cost-details':costDialog(id);break;
    case 'apply-cost':{const f=$('#costForm'),d=dataDraft.dishes.find(d=>d.id===f.dataset.id);d.costMode=f.elements.costMode.value;for(const k of ['variableCost','food','packaging','labor','other'])d[k]=readNumber(f.elements[k],k!=='variableCost');dirtyData=true;$('#dialog').close();render();break;}
    case 'import':fileInput('.csv,.tsv,.xlsx',openImport);break;
    case 'preview-import':previewImport();break;
    case 'confirm-import':if(!importState.preview)return;commitData(importState.preview.data);$('#dialog').close();navigate('data');toast(T('Menu imported. Review shared settings before checking feasibility.','菜单已导入，请核对共享设置后再判断可行性。'));break;
    case 'template-csv':download('MenuWise-menu-'+L.lang()+'.csv','\uFEFF'+I.toCSV(D.template({...state.data,dishes:state.data.dishes.map(d=>({...d,name:dish(d)}))},L.lang(),state.mode)),'text/csv;charset=utf-8');break;
    case 'template-xlsx':{const wb=new ExcelJS.Workbook(),sheet=wb.addWorksheet(T('Menu','菜单'));sheet.addRows(D.template({...state.data,dishes:state.data.dishes.map(d=>({...d,name:dish(d)}))},L.lang(),state.mode));sheet.columns.forEach(c=>c.width=25);sheet.getRow(1).font={bold:true};download('MenuWise-menu-'+L.lang()+'.xlsx',new Blob([await wb.xlsx.writeBuffer()]));break;}
    case 'backup':download('MenuWise-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');break;
    case 'restore':fileInput('.json',async file=>{try{if(file.size>10*1024*1024)throw Error();const restored=M.restore(JSON.parse(await file.text()));window.menuwisePendingRestore=restored;confirmAction(T('Restore this backup?','恢复这份备份？'),T(`This replaces the working menu and history with ${restored.scenarios.length} saved decisions.`, `将替换当前菜单和历史记录，包含 ${restored.scenarios.length} 个已保存决策。`),'confirm-restore');}catch{toast(t('invalidBackup'));}});break;
    case 'confirm-restore':state=window.menuwisePendingRestore;delete window.menuwisePendingRestore;damaged=false;L.set(state.lang);dataDraft=null;dirtyData=false;selectedDish=state.data.dishes[0].id;persist();$('#dialog').close();navigate('overview');break;
    case 'apply-capacity':{const p=collectConfig($('#decisionForm')),d=E.clone(state.data);d.settings.capacity=p.capacity;d.settings.capacityKnown=p.capacityKnown;d.settings.days=p.days;d.settings.daysKnown=p.daysKnown;d.dishes.forEach(x=>Object.assign(x,p.bounds[x.id]));commitData(d);state.configs.capacity=p;persist();render();toast(T('Operational inputs are now shared across all modules.','运营条件已供所有模块共用。'));break;}
    case 'review':review(id);break;
    case 'save-review':saveReview();$('#dialog').close();render();toast(T('Review saved.','复盘已保存。'));break;
    case 'open-report':saveReview();openReport(reportRecord());break;
    case 'delete-decision':confirmAction(T('Delete this saved decision?','删除已保存决策？'),T('This removes its snapshot and review from local history.','此操作将从本地历史中删除该快照与复盘。'),'confirm-delete-decision');$('#dialog').dataset.deleteId=id;break;
    case 'confirm-delete-decision':state.scenarios=state.scenarios.filter(s=>s.id!==$('#dialog').dataset.deleteId);persist();$('#dialog').close();render();break;
    case 'select-compare':compareIds.add(id);navigate('compare');break;
    case 'export-current':currentReport=M.snapshot('breakeven',state.data,config('breakeven'));currentReport.id='current';openReport(currentReport);break;
    case 'close-report':document.body.classList.remove('reporting');$('#reportPaper').innerHTML='';render();break;
    case 'print':window.print();break;
    case 'report-language':state.lang=L.lang()==='en'?'zh':'en';L.set(state.lang);persist();openReport(reportRecord());break;
    case 'report-html':{const style=Array.from(document.styleSheets).map(sheet=>{try{return Array.from(sheet.cssRules).map(r=>r.cssText).join('\n');}catch{return'';}}).join('\n');download('MenuWise-report-'+L.lang()+'.html',`<!doctype html><html lang="${L.lang()==='zh'?'zh-CN':'en'}"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>MenuWise</title><style>${style}</style><body class="standalone-report"><article id="reportContent">${reportContent(reportRecord())}</article></body></html>`,'text/html;charset=utf-8');break;}
  }}catch(e){const message=L.error(e,state.data);if($('#dialog').open)$('#dialog .dialog-error').textContent=message;else toast(message);}}
  document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)handleAction(a);const point=e.target.closest('[data-dish-id]');if(point){selectedDish=point.dataset.dishId;state.configs.menu=M.defaults('menu',state.data,selectedDish);navigate('menu');}});
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-dish-id]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
  document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='decisionForm')analyze(true);if(e.target.id==='dataForm')try{captureData();const d=dataDraft;if(d.source==='sample'){d.dishes.forEach(x=>x.name=dish(x,d));d.settings.name=restaurant(d);}d.source='manual';const check=commitData(d);render();toast(check.warnings.length?T('Saved. Review the warnings in your analysis.','已保存，请在分析中检查提示。'):T('Shared data saved.','共享数据已保存。'));}catch(error){$('#dataError').textContent=L.error(error,state.data);}});
  let inputTimer;
  document.addEventListener('input',e=>{if(e.target.closest('#dataForm')){dirtyData=true;$('#draftStatus').textContent=T('Unsaved changes','有未保存修改');}if(e.target.closest('#decisionForm')){clearTimeout(inputTimer);inputTimer=setTimeout(()=>analyze(),120);}if(e.target.id==='pricingSlider'){const form=$('#decisionForm');form.elements.qtyA.value=e.target.value;analyze();}if(e.target.id==='revenueSlider'){const v=Number(e.target.value),r=M.simulation(state.data,'breakeven',{},v);$('#revenueValue').textContent=cash(v);$('#revenueReadout').innerHTML=`${t('profit')}: <strong>${cash(r.profit)}</strong> · ${T('Fixed mix assumption','假设销售组合不变')}`;}if(e.target.id==='menuSearch')$$('[data-dish-name]').forEach(row=>row.hidden=!row.dataset.dishName.includes(e.target.value.trim().toLowerCase()));});
  document.addEventListener('change',e=>{const el=e.target;if(el.id==='scatterAxis')$('#menuScatter').innerHTML=scatter(state.data,el.value);if(el.name==='dishId'&&el.closest('#decisionForm')){state.configs[route]=M.defaults(route,state.data,el.value);selectedDish=el.value;render();}if(el.dataset.compareId){if(el.checked&&compareIds.size>=4){el.checked=false;toast(T('Choose up to four decisions.','最多选择四个决策。'));return;}if(el.checked)compareIds.add(el.dataset.compareId);else compareIds.delete(el.dataset.compareId);render();}if(el.id.startsWith('import')||el.dataset.mapping){if(!importState)return;if(el.id==='importSheet'){importState.sheet=Number(el.value);importState.headerIndex=0;resetMapping();importDialog();}else if(el.id==='importHeader'){importState.headerIndex=Number(el.value);resetMapping();importDialog();}else{if(el.id==='importNumber')importState.numberStyle=el.value;if(el.id==='importCost')importState.costMode=el.value;if(el.dataset.mapping)importState.mapping[el.dataset.mapping]=Number(el.value);importState.preview=null;$('#importPreview').innerHTML='';$('[data-action="confirm-import"]').disabled=true;}}});
  window.addEventListener('hashchange',()=>{if($('#dataForm'))try{captureData();}catch{}route=location.hash.slice(1);if(![...navs,'data','models'].includes(route))route='overview';render();});
  window.addEventListener('beforeunload',e=>{if(dirtyData){e.preventDefault();e.returnValue='';}});
  const report=document.createElement('section');report.id='reportPaper';document.body.append(report);C.bind();render();
})();
